{{pins}}
#include <Servo.h>
#include <Keypad.h>

char keys[4][4] = {
  { '1', '2', '3', 'A' },
  { '4', '5', '6', 'B' },
  { '7', '8', '9', 'C' },
  { '*', '0', '#', 'D' }
};
byte rowPins[4] = { KEYPAD_R1, KEYPAD_R2, KEYPAD_R3, KEYPAD_R4 };
byte colPins[4] = { KEYPAD_C1, KEYPAD_C2, KEYPAD_C3, KEYPAD_C4 };
Keypad keypad = Keypad(makeKeymap(keys), rowPins, colPins, 4, 4);
#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);  // try 0x3F if the screen stays blank

const String SECRET = "1234";
String entered = "";
int wrongTries = 0;
Servo lock;

void showPrompt() {
  lcd.clear();
  lcd.print("Enter code:");
}

void setup() {
  lcd.init();
  lcd.backlight();
  lock.attach(SERVO_PIN);
  lock.write(0);  // locked
  showPrompt();
}

void loop() {
  char key = keypad.getKey();
  if (!key) return;
  if (key == '*') {             // * locks the safe again
    lock.write(0);
    entered = "";
    showPrompt();
  } else if (key == '#') {
    lcd.clear();
    if (entered == SECRET) {
      lcd.print("OPEN");
      lock.write(90);
      wrongTries = 0;
    } else {
      wrongTries++;
      lcd.print("Wrong code");
      if (wrongTries >= 3) {
        lcd.setCursor(0, 1);
        lcd.print("Wait 10 seconds");
        delay(10000);
        wrongTries = 0;
      } else {
        delay(1500);
      }
      showPrompt();
    }
    entered = "";
  } else if (entered.length() < 8) {
    entered += key;
    lcd.setCursor(entered.length() - 1, 1);
    lcd.print('*');
  }
}
